function tr(r){if(LG!='bn')return;const w=document.createTreeWalker(r,NodeFilter.SHOW_TEXT);let n;while(n=w.nextNode()){if(n.parentNode.tagName=='OPTION')continue;const t=n.nodeValue.trim();if(BN[t])n.nodeValue=n.nodeValue.replace(t,BN[t])}r.querySelectorAll('[placeholder]').forEach(e=>{const p=e.getAttribute('placeholder');if(BN[p])e.setAttribute('placeholder',BN[p])})}
