V.stu=bs=>{const b=B.find(x=>x.id==S.bid);return `<div class="card"><h3>Batch</h3><input id="bn" placeholder="New batch name"><button onclick="f.addB()">Add batch</button>${b?`<hr>${bs}<p class="mut">Month started on (wrong date? change it, ranks recalculate)</p><input type="date" value="${b.start}" onchange="f.setStart(this.value)"><button onclick="f.newMonth()">Start new month</button>`:''}</div>
${b?`<div class="card"><h3>Add student</h3><input id="sn" placeholder="Name"><input id="sg" placeholder="Guardian phone"><input id="ss" placeholder="School"><select id="sgp"><option value="">Group (SSC/HSC only)</option><option>Science</option><option>Commerce</option><option>Arts</option></select><input id="sf" type="number" placeholder="Monthly fee"><button class="pri" onclick="f.addStu()">Add student</button></div>`:''}
<div class="card"><h3>Students</h3>${U.filter(s=>s.bid==S.bid).map(s=>`<div class="li"><span>${esc(s.name)}<br><span class="mut">Roll ${s.roll}${s.grp?' · '+s.grp:''}${s.school?' · '+esc(s.school):''}${s.active===false?' · Inactive':''}</span></span><span><button onclick="f.rp('${s.id}')">Reset password</button> <button onclick="f.tg('${s.id}')">${s.active===false?'Reactivate':'Deactivate'}</button></span></div>`).join('')||'<p class="mut">No students yet.</p>'}</div>`};
f.addB=async()=>{const n=$('#bn').value.trim();if(!n)return;await addDoc(collection(db,'batches'),{name:n,start:T()});render()};
