V.ex=async bs=>{if(!S.bid)return nob;const E=(await snap('exams',where('bid','==',S.bid))).sort((x,y)=>y.date>x.date?1:-1),e=E.find(x=>x.id==S.eid)||E[0];S.E=e;if(e){S.eid=e.id;if(!e.subs[S.si])S.si=0}const u=e&&e.subs[S.si];
return `${bs}<div class="card"><h3>New exam</h3><input id="et" placeholder="Exam name"><input id="ed" type="date" value="${T()}"><input id="es" placeholder="Bangla 100, English 50"><button onclick="f.addEx()">Create exam</button></div>
${e?`<select onchange="S.eid=this.value;S.si=0;f.r()">${E.map(x=>`<option value="${x.id}" ${x.id==e.id?'selected':''}>${esc(x.title)} · ${x.date}</option>`).join('')}</select><div class="bar">${e.subs.map((x,i)=>`<button class="${i==S.si?'on':''}" onclick="S.si=${i};f.r()">${esc(x.n)} · ${x.st=='H'?'Held':'Not Happened'}</button>`).join('')}</div>
<div class="card"><b>${e.pub===false?'Hidden from students':'Published to students'}</b>${pubOK()?` <button onclick="f.pub(${e.pub===false})">${e.pub===false?'Publish results':'Hide results'}</button>`:'<p class="mut">Marks stay hidden until a teacher with publish permission, or the admin, publishes.</p>'}</div><div class="card"><label><input type="checkbox" style="width:auto" ${u.st=='H'?'checked':''} onchange="f.held(this.checked)"> Exam held · out of ${u.total}</label><p class="mut">Held + blank = Absent (0). Not Happened is left out.</p>${act().map(s=>`<div class="li"><span>${esc(s.name)}<br><span class="mut">${s.roll}</span></span><input type="number" style="width:90px;margin:0" max="${u.total}" ${u.st=='H'?'':'disabled'} placeholder="Absent (0)" value="${u.m[s.id]??''}" oninput="f.setM('${s.id}',this.value)"></div>`).join('')}<button class="pri" onclick="f.saveEx()">Save marks</button></div>`:''}`};
const putEx=async()=>{const {id,...x}=S.E;await setDoc(doc(db,'exams',id),x);await recalc(S.bid)};
f.addEx=async()=>{const t=$('#et').value.trim(),subs=$('#es').value.split(',').map(x=>x.trim().match(/^(.+?)\s+(\d+)$/)).filter(Boolean).map(x=>({n:x[1],total:+x[2],st:'NH',m:{}}));
if(!t||!subs.length)return alert('Add a name and subjects like: Bangla 100, English 50');const r=await addDoc(collection(db,'exams'),{bid:S.bid,title:t,date:$('#ed').value||T(),subs,pub:false});S.eid=r.id;S.si=0;render()};
f.held=async on=>{S.E.subs[S.si].st=on?'H':'NH';await putEx();render()};
f.setM=(id,v)=>{const u=S.E.subs[S.si];if(v==='')delete u.m[id];else u.m[id]=Math.min(+v,u.total)};
f.saveEx=async()=>{await putEx();alert('Marks saved')};
V.fee=async bs=>{if(!S.bid)return nob;const L=act(),P=await snap('pay',where('m','==',S.fm)),pd=id=>P.filter(p=>p.sid==id).reduce((a,p)=>a+p.amt,0);
return `${bs}<input type="month" value="${S.fm}" onchange="S.fm=this.value;f.r()"><div class="card"><h3>Add payment</h3><select id="ps">${L.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select><input id="pa" type="number" placeholder="Amount"><select id="pm"><option>Cash</option><option>bKash</option><option>Nagad</option></select><input id="pt" placeholder="Transaction ID (online only)"><button class="pri" onclick="f.addPay()">Add payment</button></div>
<div class="card"><h3>${S.fm}</h3>${L.map(s=>{const p=pd(s.id),t=!s.fee?['No fee','']:p>=s.fee?['Paid','ok']:p>0?['Partial','warn']:['Due','bad'];return `<div class="li"><span>${esc(s.name)}<br><span class="mut">৳${p} of ৳${s.fee||0}</span></span><b class="${t[1]}">${t[0]}</b></div>`}).join('')}</div>`};
f.addPay=async()=>{const a=+$('#pa').value,t=$('#pt').value.trim();if(!(a>0))return alert('Enter the amount');if(t&&(await snap('pay',where('tx','==',t))).length)return alert('This Transaction ID is already used');
const ps=$('#ps').value;await addDoc(collection(db,'pay'),{sid:ps,m:S.fm,amt:a,method:$('#pm').value,tx:t});nt(ps,'Payment received: ৳'+a+' ('+S.fm+')');render()};
async function chg(){while(me.mustChange){const np=prompt('First login: choose a new password (min 6 characters)');if(np&&np.length>=6)try{await updatePassword(auth.currentUser,np);await updateDoc(doc(db,'users',me.id),{mustChange:false});me.mustChange=false}catch(e){alert(e.message)}}}
async function student(){await chg();const s=me.stats||{};S.pg=S.pg||'dash';const CH=chrome(SI,S.pg,k=>`f.pg('${k}')`);if(S.pg=='pf')return out(CH+profHtml());out(`${CH}<div class="card" data-pg="dash"><h3>This month</h3><div class="rings">${ring(s.ex,'Exam','#2f80ed')}${ring(s.ov,'Overall','var(--pri)')}${ring(s.hw,'Homework','#e3a51b')}${ring((s.p||0)+(s.a||0)?s.p/((s.p||0)+(s.a||0))*100:null,'Attendance','#1d7a4c')}</div><span class="chip2"><span>Exam rank</span> #${s.er||'–'} / ${s.n||'–'}</span><span class="chip2"><span>Overall rank</span> #${s.or||'–'} / ${s.n||'–'}</span></div><div class="card" data-pg="nt"><h3>Notifications</h3><div id="nl">Loading…</div></div><div class="card" data-pg="rq"><h3>My requests</h3><select id="rt" onchange="f.rqT()">${Object.entries(RT).map(([k,v])=>`<option value="${k}">${tl(v)}</option>`).join('')}</select><input id="rd" placeholder="Details / reason"><div id="rl2" hidden><input id="rf" type="date"><input id="re" type="date"></div><select id="rg" hidden><option>Science</option><option>Commerce</option><option>Arts</option></select><input id="rs" placeholder="New school / college name" hidden><button class="pri" onclick="f.rqSend()">Send request</button><div id="rql"></div></div><div class="card" data-pg="hw"><h3>Homework</h3><div id="hl">Loading…</div></div><div class="card" data-pg="rp"><h3>Progress reports</h3><div id="pr">Loading…</div></div><div class="card" data-pg="fee"><h3>Fees</h3><div id="pl">Loading…</div></div><div class="card" data-pg="sy"><h3>Syllabus status</h3><div id="syl">Loading…</div></div><div class="card" data-pg="sg"><h3>Suggestions</h3><div id="sgl">Loading…</div></div><div class="card" data-pg="sl"><h3>Exam solutions</h3><div id="sll">Loading…</div></div><div class="card" data-pg="rec"><h3>Past months</h3><div id="ph">Loading…</div></div>`);
showPg();fileShow();syShow();ntShow();rqShow();snap('hw',where('bid','==',me.bid)).then(H=>$('#hl').innerHTML=H.sort((x,y)=>y.date>x.date?1:-1).slice(0,20).map(h=>`<div class="li"><span>${esc(h.title)}<br><span class="mut">${h.date}</span></span><b class="${h.D.includes(me.id)?'ok':'bad'}">${h.D.includes(me.id)?'Done':'Not Done'}</b></div>`).join('')||'<p class="mut">No homework yet.</p>');
getDocs(collection(db,'users',me.id,'hist')).then(q=>$('#ph').innerHTML=q.docs.map(d=>d.data()).sort((x,y)=>y.to>x.to?1:-1).map(h=>`<div class="li"><span>${h.from} to ${h.to}<br><span class="mut">Exam ${f1(h.ex)} (#${h.er||'–'}) · Overall ${f1(h.ov)} (#${h.or||'–'})</span></span></div>`).join('')||'<p class="mut">No past months yet.</p>');
getDocs(collection(db,'users',me.id,'reports')).then(q=>{q.docs.forEach(d=>RP[d.id]=d.data());$('#pr').innerHTML=q.docs.map(d=>`<div class="li"><span>${d.data().from} to ${d.data().to}</span><button onclick="f.vr('${d.id}')">View / Save PDF</button></div>`).join('')||'<p class="mut">No report published yet.</p>'});
const P=await snap('pay',where('sid','==',me.id));$('#pl').innerHTML=P.sort((x,y)=>y.m>x.m?1:-1).map(p=>`<div class="li"><span>${p.m}</span><span>৳${p.amt} · ${esc(p.method)}</span></div>`).join('')||'<p class="mut">No payments yet.</p>'}

V.mo=bs=>{const b=B.find(x=>x.id==S.bid);if(!b)return nob;const R=U.filter(s=>s.bid==S.bid&&s.stats).sort((x,y)=>(x.stats.er||999)-(y.stats.er||999));
const av_=k=>{const a=R.map(x=>x.stats[k]).filter(v=>v!=null);return a.length?a.reduce((x,y)=>x+y)/a.length:null};
return `${bs}<div class="card"><h3>Batch average</h3><div class="rings">${ring(av_('ex'),'Exam','#2f80ed')}${ring(av_('ov'),'Overall','var(--pri)')}${ring(av_('hw'),'Homework','#e3a51b')}</div></div><div class="card"><h3>Month</h3><p class="mut">Started on (wrong date? change it, ranks recalculate)</p><input type="date" value="${b.start}" onchange="f.setStart(this.value)"><button onclick="f.newMonth()">Start new month</button></div><div class="card"><h3>Rank</h3>${R.map(s=>`<div class="li"><span>${esc(s.name)}</span><span>Exam ${f1(s.stats.ex)} (#${s.stats.er||'–'}) · Overall ${f1(s.stats.ov)} (#${s.stats.or||'–'})</span></div>`).join('')||'<p class="mut">No data yet.</p>'}</div>`};
V.tch=()=>`<div class="card"><h3>Add teacher</h3><input id="tn" placeholder="Name"><input id="tj" placeholder="Subject"><input id="tp" placeholder="Phone"><button class="pri" onclick="f.addTch()">Add teacher</button></div>${TC.map(t=>`<div class="card"><b>${esc(t.name)}</b> <span class="mut">Roll ${t.roll} · ${esc(t.subject||'')}${t.active===false?' · Inactive':''}</span><label class="li"><span>Can publish results</span><input type="checkbox" style="width:auto;margin:0" ${t.pub?'checked':''} onchange="f.pubT('${t.id}',this.checked)"></label><p class="mut">Tick the batches this teacher can use:</p>${B.map(b=>`<label class="li"><span>${esc(b.name)}</span><input type="checkbox" style="width:auto;margin:0" ${(t.bids||[]).includes(b.id)?'checked':''} onchange="f.asg('${t.id}','${b.id}',this.checked)"></label>`).join('')||'<p class="mut">Add a batch first.</p>'}<button onclick="f.rp('${t.id}')">Reset password</button> <button onclick="f.tgT('${t.id}')">${t.active===false?'Reactivate':'Deactivate'}</button></div>`).join('')||'<p class="mut">No teachers yet.</p>'}`;
f.addTch=async()=>{const n=$('#tn').value.trim();if(!n)return alert('Enter the name');let r;do r=String(100000+Math.floor(Math.random()*900000));while(U.some(s=>s.roll==r)||TC.some(s=>s.roll==r));
const pw=Math.random().toString(36).slice(2,8)+'A1',a2=getAuth(initializeApp(cfg,'s'+Date.now()));
try{const c=await createUserWithEmailAndPassword(a2,em(r),pw);await signOut(a2);await setDoc(doc(db,'users',c.user.uid),{role:'teacher',name:n,roll:r,subject:$('#tj').value,phone:$('#tp').value,bids:[],active:true,mustChange:true});
alert('Roll (username): '+r+'\nPassword: '+pw+'\nGive this to the teacher.');render()}catch(e){alert(e.message)}};
f.asg=async(t,b,on)=>{const x=TC.find(q=>q.id==t),z=new Set(x.bids||[]);on?z.add(b):z.delete(b);x.bids=[...z];await updateDoc(doc(db,'users',t),{bids:x.bids})};
f.tgT=async id=>{const t=TC.find(x=>x.id==id);await updateDoc(doc(db,'users',id),{active:t.active===false});render()};

V.hw=async bs=>{if(!S.bid)return nob;const H=(await snap('hw',where('bid','==',S.bid))).sort((x,y)=>y.date>x.date?1:-1),h=H.find(x=>x.id==S.hid)||H[0];S.H=h;if(h)S.hid=h.id;
return `${bs}<div class="card"><h3>Give homework</h3><input id="ht" placeholder="Homework, e.g. Algebra ex 3.2"><input id="hd" type="date" value="${T()}"><button class="pri" onclick="f.addHw()">Give homework</button></div>
${h?`<select onchange="S.hid=this.value;f.r()">${H.map(x=>`<option value="${x.id}" ${x.id==h.id?'selected':''}>${esc(x.title)} · ${x.date}</option>`).join('')}</select><div class="card"><p class="mut">Tap a name to switch Not Done / Done, then Save.</p>${act().map(s=>`<button id="h${s.id}" class="stu ${h.D.includes(s.id)?'':'A'}" onclick="f.hd('${s.id}')"><span>${esc(s.name)}</span><i>${h.D.includes(s.id)?'Done':'Not Done'}</i></button>`).join('')}<button onclick="f.hAll()">Mark all Done</button> <button class="pri" onclick="f.saveHw()">Save</button></div>`:''}`};
f.addHw=async()=>{const t=$('#ht').value.trim();if(!t)return alert('Write the homework');const r=await addDoc(collection(db,'hw'),{bid:S.bid,title:t,date:$('#hd').value||T(),D:[]});S.hid=r.id;render()};
f.hd=id=>{const D=S.H.D,i=D.indexOf(id);i<0?D.push(id):D.splice(i,1);const e=$('#h'+id);e.className='stu '+(i<0?'':'A');e.lastChild.textContent=i<0?'Done':'Not Done'};
f.hAll=()=>act().forEach(s=>{if(!S.H.D.includes(s.id))f.hd(s.id)});
f.saveHw=async()=>{const {id,...x}=S.H;await setDoc(doc(db,'hw',id),x);await recalc(S.bid);alert('Saved')};

const pubOK=()=>me.role=='admin'||me.pub===true;
f.pub=async on=>{S.E.pub=on;await putEx();render()};
f.pubT=async(id,on)=>{await updateDoc(doc(db,'users',id),{pub:on});TC.find(t=>t.id==id).pub=on};
V.rec=async bs=>{if(!S.bid)return nob;const R=(await snap('records',where('bid','==',S.bid))).sort((x,y)=>y.to>x.to?1:-1);
return `${bs}<div class="card"><h3>Past months</h3>${R.map(r=>`<details><summary>${r.from} to ${r.to}</summary><div style="overflow-x:auto"><table style="width:100%;font-size:14px;border-collapse:collapse"><tr><th align="left">Name</th><th>Exam</th><th>#</th><th>Overall</th><th>#</th></tr>${r.rows.sort((x,y)=>(x.er||999)-(y.er||999)).map(x=>`<tr><td>${esc(x.name||'Roll '+x.roll)}</td><td>${f1(x.ex)}</td><td>${x.er||'–'}</td><td>${f1(x.ov)}</td><td>${x.or||'–'}</td></tr>`).join('')}</table></div></details>`).join('')||'<p class="mut">Closed months are saved here automatically.</p>'}</div>`};

f.rp=async id=>{const u=U.find(x=>x.id==id)||TC.find(x=>x.id==id);if(!confirm('Reset password for '+u.name+'?'))return;const e=u.roll+'-'+Date.now().toString(36)+'@rise.local',pw=Math.random().toString(36).slice(2,8)+'A1',a2=getAuth(initializeApp(cfg,'s'+Date.now()));
try{const c=await createUserWithEmailAndPassword(a2,e,pw);await signOut(a2);await setDoc(doc(db,'map',c.user.uid),{sid:id});await setDoc(doc(db,'login',u.roll),{e});await updateDoc(doc(db,'users',id),{mustChange:true});alert('New password for roll '+u.roll+': '+pw+'\nThey must change it at first login.')}catch(x){alert(x.message)}};
async function calc(bid,from,to){const L=(await snap('users',where('bid','==',bid))).filter(s=>s.role=='student'&&s.active!==false),A=(await snap('att',where('bid','==',bid))).filter(d=>d.date>=from&&d.date<=to),E=(await snap('exams',where('bid','==',bid))).filter(e=>e.date>=from&&e.date<=to&&e.pub!==false),H=(await snap('hw',where('bid','==',bid))).filter(h=>h.date>=from&&h.date<=to);
const R=L.map(s=>{let p=0,a=0,g=0,t=0;const it=[];A.forEach(d=>{if(d.A.includes(s.id))a++;else if(!d.E.includes(s.id))p++});E.forEach(e=>e.subs.forEach(u=>{if(u.st=='H'){const m=+(u.m[s.id]||0);t+=u.total;g+=m;it.push({n:e.title+' – '+u.n,g:m,t:u.total})}}));
const at=p+a?p/(p+a)*100:null,hw=H.length?H.filter(h=>h.D.includes(s.id)).length/H.length*100:null,pr=[at,hw].filter(v=>v!=null);return{s,it,p,a,days:A.length,at,ex:t?g/t*100:null,ov:pr.length?pr.reduce((x,y)=>x+y)/pr.length:null}});
const rk=k=>{const v=[...new Set(R.filter(r=>r[k]!=null).map(r=>Math.round(r[k]*100)))].sort((x,y)=>y-x);return r=>r[k]==null?null:v.indexOf(Math.round(r[k]*100))+1},re=rk('ex'),ro=rk('ov');return R.map(r=>({...r,er:re(r),or:ro(r),n:R.length}))}
const rpRing=v=>{const p=v==null?0:Math.min(100,Math.max(0,v)),R=40,C=2*Math.PI*R;return `<svg viewBox="0 0 100 100" width="96" height="96"><circle cx="50" cy="50" r="${R}" fill="none" stroke="#dbe5f1" stroke-width="11"/><circle cx="50" cy="50" r="${R}" fill="none" stroke="#1f4068" stroke-width="11" stroke-dasharray="${(p/100*C).toFixed(1)} ${C.toFixed(1)}" transform="rotate(-90 50 50)"/><text x="50" y="57" text-anchor="middle" font-size="22" font-weight="700" fill="#13294b">${v==null?'–':Math.round(v)+'%'}</text></svg>`};
const rhtml=d=>{const sp=x=>{const q=x.n.split(' – ');return q.length>1?[q.slice(1).join(' – '),q[0]]:[x.n,'']},TT=d.it.reduce((a,x)=>a+x.t,0),GG=d.it.reduce((a,x)=>a+x.g,0),H=(t,c)=>`<div style="background:${c};color:#fff;padding:9px 14px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;border-radius:6px 6px 0 0">${t}</div>`,BX='border:1px solid #9fb6d1;background:#f3f7fc;border-radius:0 0 6px 6px;padding:12px 14px',TD='padding:8px;border-top:1px solid #b8c9e0';
return `<div style="max-width:720px;margin:auto;font:14px/1.45 Georgia,'Noto Serif Bengali',serif;color:#13294b">
<div style="display:flex;align-items:center;gap:14px;margin-bottom:14px"><img src="logo.jpg" alt="" style="width:84px;height:84px;border-radius:50%"><div style="flex:1;text-align:center"><div style="font-size:24px;font-weight:800;text-transform:uppercase">${esc(INST.name||'Rise Edge Academy')}</div><div style="display:flex;align-items:center;gap:8px;margin-top:4px"><span style="flex:1;border-top:2px solid #13294b"></span><b style="letter-spacing:.14em;font-size:12px">STUDENT PROGRESS REPORT</b><span style="flex:1;border-top:2px solid #13294b"></span></div></div></div>
${H('Student Information','#8b2332')}<div style="${BX};display:grid;grid-template-columns:1fr 1fr;gap:8px 18px"><div><b>Student:</b> ${esc(d.name)}</div><div><b>Batch:</b> ${esc(d.bn)}</div><div><b>Roll:</b> ${d.roll}</div><div><b>Report Period:</b> ${d.from} to ${d.to}</div></div>
<table style="width:100%;border-collapse:collapse;margin:14px 0;border:1px solid #9fb6d1"><tr style="background:#8b2332;color:#fff"><th style="padding:8px;text-align:left">Subject</th><th style="padding:8px;text-align:left">Assessment</th><th style="padding:8px;text-align:left">Marks</th></tr>${d.it.map(x=>{const [a,b]=sp(x);return `<tr><td style="${TD}"><b>${esc(a)}</b></td><td style="${TD}">${esc(b)}</td><td style="${TD}">${x.g} / ${x.t}</td></tr>`}).join('')||'<tr><td colspan="3" style="padding:8px">No exam in this period</td></tr>'}</table>
<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:12px;margin-bottom:14px"><div>${H('Exam Performance','#1f4068')}<div style="${BX};display:flex;align-items:center;gap:12px">${rpRing(d.ex)}<div><b style="font-size:20px">${f1(d.ex)}</b><div style="font-size:11px">Marks (${d.it.map(x=>x.g+'/'+x.t).join(' + ')||'–'})</div></div></div></div><div>${H('Attendance','#1f4068')}<div style="${BX};display:flex;align-items:center;gap:12px">${rpRing(d.at)}<div><b style="font-size:20px">${f1(d.at)}</b><div style="font-size:12px">present ${d.p} of ${d.days} class days</div></div></div></div></div>
${H('Grading / Performance Overview','#1f4068')}<div style="${BX};display:flex;gap:16px;align-items:center;margin-bottom:14px"><div style="flex:1"><b>Total:</b> <span style="font-size:24px;font-weight:700">${GG} / ${TT}</span></div><div style="flex:1;border-left:1px solid #9fb6d1;padding-left:16px"><b>Overall Rank:</b> <span style="font-size:24px;font-weight:700">${d.or||'–'}</span><div style="font-size:12px">Exam rank ${d.er||'–'} of ${d.n}</div></div></div>
${H("Teacher's Comment",'#8b2332')}<div style="${BX};background:#fff;min-height:70px">${esc(d.cm||'')}</div>
<div style="display:flex;justify-content:space-between;gap:8px;font-size:12px;margin-top:6px"><span>${esc(INST.owner||'')} ${esc(INST.phone||'')}</span><span>Generated: ${d.date}</span></div></div>`};
const showR=h=>{const e=$('#rp');e.innerHTML='<div class="no"><button onclick="window.print()">Save as PDF / Print</button> <button onclick="document.getElementById(\'rp\').hidden=true">Close</button></div>'+h;e.hidden=false};
f.vr=id=>showR(rhtml(RP[id]));
const snapOf=(r,cm)=>({bn:B.find(b=>b.id==S.bid).name,from:S.rf,to:S.rt,name:r.s.name,roll:r.s.roll,it:r.it,p:r.p,a:r.a,days:r.days,at:r.at,ex:r.ex,er:r.er,ov:r.ov,or:r.or,n:r.n,cm,date:T()});
V.rep=async bs=>{if(!S.bid)return nob;const b=B.find(x=>x.id==S.bid);S.rf=S.rf||b.start;S.rt=S.rt||T();S.R=await calc(S.bid,S.rf,S.rt);const d=await getDoc(doc(db,'rep',S.bid+'_'+S.rf+'_'+S.rt)),c=d.exists()?d.data().c:{};
return `${bs}<div class="card"><h3>Report period</h3><input type="date" value="${S.rf}" onchange="S.rf=this.value;f.r()"><input type="date" value="${S.rt}" onchange="S.rt=this.value;f.r()"><p class="mut">Only published exams are counted. One comment per student.</p></div>
<div class="card">${S.R.map(r=>`<div class="li" style="display:block"><b>${esc(r.s.name)}</b> <span class="mut">Roll ${r.s.roll}</span><input class="cm" data-id="${r.s.id}" placeholder="Teacher's comment" value="${esc(c[r.s.id]||'')}" style="margin:6px 0"><button onclick="f.pv('${r.s.id}')">Preview / PDF</button></div>`).join('')||'<p class="mut">No students.</p>'}<button onclick="f.sr(false)">Save comments</button> ${me.role=='teacher'&&me.pub?'<button class="pri" onclick="f.sr(true)">Publish to students</button>':'<p class="mut">Only a teacher with publish permission can publish reports.</p>'}</div>
${me.role=='admin'?`<div class="card"><h3>Institute (shown on reports)</h3><input id="in" placeholder="Coaching name" value="${esc(INST.name||'')}"><input id="io" placeholder="Owner name" value="${esc(INST.owner||'')}"><input id="ip" placeholder="Owner phone" value="${esc(INST.phone||'')}"><button onclick="f.si()">Save</button></div>`:''}`};
const cms=()=>{const c={};document.querySelectorAll('.cm').forEach(i=>{if(i.value.trim())c[i.dataset.id]=i.value.trim()});return c};
f.pv=id=>{const r=S.R.find(x=>x.s.id==id);showR(rhtml(snapOf(r,cms()[id]||'')))};
f.sr=async pub=>{const c=cms();await setDoc(doc(db,'rep',S.bid+'_'+S.rf+'_'+S.rt),{bid:S.bid,from:S.rf,to:S.rt,c});if(pub){await Promise.all(S.R.map(r=>setDoc(doc(db,'users',r.s.id,'reports',S.rf+'_'+S.rt),snapOf(r,c[r.s.id]||''))))}alert(pub?'Published to students':'Comments saved')};
f.si=async()=>{INST={name:$('#in').value,owner:$('#io').value,phone:$('#ip').value};await setDoc(doc(db,'config','inst'),INST);alert('Saved')};

f.lang=()=>{localStorage.setItem('lg',LG=='bn'?'en':'bn');location.reload()};
const nt=(to,t,bid)=>addDoc(collection(db,'nt'),{to,t,d:Date.now(),...(bid?{bid}:{})}).catch(()=>{});
async function ntGet(){let q;if(me.role=='student')q=await Promise.all([snap('nt',where('to','==','batch'),where('bid','==',me.bid)),snap('nt',where('to','==',me.id))]);
else if(me.role=='teacher')q=await Promise.all((me.bids||[]).map(b=>snap('nt',where('to','==','batch'),where('bid','==',b))));else q=[await snap('nt',where('to','==','admin'))];
return q.flat().sort((a,b)=>b.d-a.d).slice(0,30)}
const nrow=(n,sn)=>`<div class="li"><span>${esc(n.t)}<br><span class="mut">${new Date(n.d).toLocaleString()}</span></span>${n.d>sn?'<b class="bad">NEW</b>':''}</div>`;
async function ntShow(){try{const L=await ntGet(),k='seen'+me.id,sn=+localStorage.getItem(k)||0;$('#nl').innerHTML=L.slice(0,8).map(n=>nrow(n,sn)).join('')||'<p class="mut">No notifications.</p>';localStorage.setItem(k,Date.now())}catch(e){$('#nl').textContent=''}}
V.nt=async bs=>{const L=await ntGet(),k='seen'+me.id,sn=+localStorage.getItem(k)||0;localStorage.setItem(k,Date.now());
return `${bs}<div class="card"><h3>Send notice to this batch</h3><input id="nm" placeholder="Write the notice"><button class="pri" onclick="f.sendN()">Send</button></div><div class="card"><h3>Notifications</h3>${L.map(n=>nrow(n,sn)).join('')||'<p class="mut">No notifications.</p>'}</div>`};
f.sendN=async()=>{const t=$('#nm').value.trim();if(!t||!S.bid)return;await nt('batch',t,S.bid);alert('Sent');render()};
const W=(k,g)=>{const o=f[k];f[k]=async(...a)=>{const c=g(...a);await o(...a);c&&c()}},bn=()=>(B.find(b=>b.id==S.bid)||{}).name,tn=()=>me.role=='teacher';
W('addHw',()=>{const t=$('#ht').value.trim();return t&&(()=>nt('batch','New homework: '+t,S.bid))});
W('addEx',()=>{const t=$('#et').value.trim();return t&&(()=>nt('batch','New exam: '+t,S.bid))});
W('pub',on=>on&&(()=>nt('batch','Results published: '+S.E.title,S.bid)));
W('sr',p=>p&&(()=>nt('batch','Progress report published',S.bid)));
