const flv=async(bs,kind,ttl)=>{if(!S.bid)return nob;const L=(await snap('fl',where('bid','==',S.bid),where('kind','==',kind))).sort((a,b)=>b.t-a.t);
return `${bs}<div class="card"><h3>Upload</h3><input id="ft" placeholder="Title"><input id="fk" placeholder="Link (Google Drive etc.), or choose a file below"><input id="ff" type="file" accept="application/pdf,image/*"><p class="mut">File max 700 KB. For bigger files use a link.</p><button class="pri" onclick="f.up('${kind}')">Upload</button></div><div class="card"><h3>${ttl}</h3>${L.map(x=>`<div class="li"><span>${esc(x.title)}<br><span class="mut">${new Date(x.t).toLocaleDateString()}</span></span><span><button onclick="f.dl('${x.id}')">Open</button> <button onclick="f.fdel('${x.id}')">Delete</button></span></div>`).join('')||'<p class="mut">Nothing yet.</p>'}</div>`};
